python3 -c "
import json
with open('/app/resources/treasury_bulletin_1980_05.json') as f:
    data = json.load(f)

# Print keys at top level
if isinstance(data, dict):
    def print_structure(d, indent=0):
        if indent > 4:
            return
        if isinstance(d, dict):
            for k, v in d.items():
                print('  ' * indent + str(k))
                if isinstance(v, (dict, list)) and indent < 3:
                    print_structure(v, indent+1)
        elif isinstance(d, list) and len(d) > 0:
            print('  ' * indent + f'[list of {len(d)} items]')
            if indent < 2:
                print_structure(d[0], indent+1)
    print_structure(data)
"

